public abstract class Superpower {
    protected abstract void activate();               // the sandbox method
    protected final void playSound(SoundId id, double volume) { /* engine call */ }
    protected void spawnParticles(ParticleType t, int count) { /* engine call */ }
}

final class SkyLaunch extends Superpower {
    @Override protected void activate() {             // composes primitives only
        playSound(SoundId.SPROING, 1.0);
        spawnParticles(ParticleType.DUST, 10);
    }
}

